import React, { useState } from 'react';

export default function PalindromeChecker() {
  const [input, setInput] = useState('');
  const [isPalindrome, setIsPalindrome] = useState(null);

  const checkPalindrome = (text) => {
    const cleaned = text.toLowerCase().replace(/[^a-z0-9]/gi, '');
    const reversed = cleaned.split('').reverse().join('');
    return cleaned && cleaned === reversed;
  };

  const handleChange = (e) => {
    const value = e.target.value;
    setInput(value);
    setIsPalindrome(checkPalindrome(value));
  };

  return (
    <div className="flex flex-col items-center justify-center h-screen bg-gray-100 p-6">
      <div className="bg-white p-6 rounded-2xl shadow-md w-full max-w-md ">
        <h1 className="text-2xl font-bold mb-4 text-center">Palindrome Checker</h1>
        <input
          type="text"
          value={input}
          onChange={handleChange}
          placeholder="Enter a word or phrase"
          className="w-full p-3 border border-gray-300 rounded-xl mb-4 align-items-center"
        />
        {input && (
          <p className={`text-center text-lg font-medium ${isPalindrome ? 'text-green-600' : 'text-red-600'}`}>
            {isPalindrome ? `"${input}" is a Palindrome!` : `"${input}" is Not a Palindrome.`}
          </p>
        )}
      </div>
    </div>
  );
}
